import copy

def transform_hypothesis(grid, pattern):
    """Pattern placed starting AT each 7's column, extending rightward"""
    new_grid = copy.deepcopy(grid)

    # Find all positions of 7
    positions_7 = []
    for r in range(len(new_grid)):
        for c in range(len(new_grid[r])):
            if new_grid[r][c] == 7:
                positions_7.append((r, c))

    for r, c in positions_7:
        # Place pattern starting at column c, extending right
        # But we need to ensure we don't go out of bounds
        for i, val in enumerate(pattern):
            col_idx = c + i
            if col_idx < len(new_grid[r]):
                new_grid[r][col_idx] = val

    return new_grid

